/* @component: nature-video */
(function () {
  const plyrCss = 'https://cdn.plyr.io/3.7.8/plyr.css';
  const plyrJs = 'https://cdn.plyr.io/3.7.8/plyr.js';
  function loadScript(id, src, cb) {
    if (typeof Plyr !== 'undefined') { cb(); return; }
    let s = document.getElementById(id);
    if (!s) {
      s = document.createElement('script');
      s.id = id;
      s.src = src;
      s.onload = cb;
      document.head.appendChild(s);
    } else {
      s.addEventListener('load', cb);
    }
  }
  function initPlayer() {
    document.querySelectorAll('.nature-video .video-player').forEach(function (v) {
      if (v.dataset.initialized === 'true' || v.plyr) return;
      v.dataset.initialized = 'true';
      new Plyr(v, {
        controls: ['play-large', 'play', 'progress', 'current-time', 'mute', 'volume', 'captions', 'settings', 'pip', 'airplay', 'fullscreen'],
        ratio: '16:9',
        autoplay: false
      });
    });
  }
  if (!document.getElementById('plyr-css')) {
    const l = document.createElement('link');
    l.id = 'plyr-css';
    l.rel = 'stylesheet';
    l.href = plyrCss;
    document.head.appendChild(l);
  }
  loadScript('plyr-js', plyrJs, function () {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initPlayer);
    } else {
      initPlayer();
    }
    setTimeout(initPlayer, 300);
  });
})();
/* @end: nature-video */
